// MCP Server Integration for Unified Safecast Server
// Starts MCP server on separate port (default 3333)
// Requires: PostgreSQL (main DB), DuckDB (optional for analytics), ANTHROPIC_API_KEY (optional, for web chat)

package main

import (
	"bytes"
	"context"
	"encoding/json"
	"fmt"
	"io"
	"log"
	"net/http"
	"os"
	"path/filepath"
	"strings"
